import { addCollection, Icon as IconifyIcon, type IconifyJSON, type IconProps as IconifyIconProps } from '@iconify/react/offline'
import lucideSubset from './icons/lucide-subset.json'

// The icons ship inside the bundle: the offline build has no API loader, so a
// name that is not in this subset renders nothing instead of being fetched.
// The subset is generated by scripts/build-icon-subset.mjs from the
// @iconify-json/lucide package (ISC license, see the `info` block in the file).
addCollection(lucideSubset as IconifyJSON)

/** Icon props: the iconify props, with `icon` always given as a string name. */
export type IconProps = Omit<IconifyIconProps, 'icon'> & {
  /** A lucide name such as "arrow-up", or a full iconify name such as "lucide:tag". */
  icon: string
}

const DEFAULT_SET = 'lucide'

/**
 * The app's icon. A bare name is looked up in the lucide set; a name that
 * already carries a set ("set:name") is used as is. Icons are decorative by
 * default and hidden from screen readers, unless the caller gives them an
 * accessible name (`aria-label` or `title`) or sets `aria-hidden` itself.
 */
export function Icon({ icon, ...rest }: IconProps) {
  const fullName = icon.includes(':') ? icon : `${DEFAULT_SET}:${icon}`
  // iconify's prop type has no `title`, but a caller may still spread one in.
  const title = (rest as { title?: unknown }).title
  const labelled = rest['aria-label'] !== undefined || title !== undefined
  // Pass an explicit false when labelled: iconify adds aria-hidden="true" on its own otherwise.
  const ariaHidden = rest['aria-hidden'] ?? !labelled

  return <IconifyIcon {...rest} icon={fullName} aria-hidden={ariaHidden} />
}

export default Icon
